       value = function() { e <- eigen(matrix(c(1, -2, 0, 3, 1, 0, 0, 0, 0.5), 3, byrow = TRUE), only.values = TRUE)$values; c(Re(e), Im(e)) }),
  list(id = "ginv", title = "Moore-Penrose inverse of a rank-1 matrix (MASS::ginv)",
       value = function() c(t(MASS::ginv(matrix(c(1, 2, 2, 4, 3, 6), 3, byrow = TRUE)))))
)

if (!exists(".rstats_oracle")) {
  for (ex in examples) {
    cat(sprintf("%s: %s\n", ex$id, ex$title))
    cat(" ", sprintf("%.17g", ex$value()), "\n")
  }
}
